import React, { useMemo, useState } from "react";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ComposedChart, Legend, Line, LineChart, ReferenceLine, ResponsiveContainer, Scatter, ScatterChart, Tooltip, XAxis, YAxis } from "recharts";
import { APP_VERSION } from "./version.js";

const sections = ["overview", "journeys", "driving", "charging", "battery", "activity", "report", "quality", "data"];
const iconPaths = {
  overview: "M4 13h6V4H4v9Zm10 7h6v-9h-6v9ZM4 20h6v-3H4v3Zm10-13h6V4h-6v3Z",
  journeys: "M5 19c4-8 10-3 14-14M14 5h5v5", charging: "M13 2 5 14h6l-1 8 8-12h-6l1-8Z",
  driving: "M4 16c2-5 5-8 8-8s6 3 8 8M8 16h8M12 8V4",
  battery: "M3 7h17v12H3V7Zm17 4h2v4h-2M6 10h7v6H6v-6Z", activity: "M4 19V9m5 10V5m5 14v-7m5 7V3",
  report: "M6 2h9l4 4v16H6V2Zm9 0v5h4M9 11h7M9 15h7M9 19h5", quality: "m4 12 5 5L20 6", data: "M12 3v12m-5-5 5 5 5-5M5 20h14",
};
const C = { mint: "#20a983", teal: "#3ab5ae", cyan: "#63b7d4", amber: "#e3a62f", coral: "#e27b66", violet: "#8a82d5" };
const phaseKeys = { runtime_load:"phaseRuntimeLoad", engine_init:"phaseEngineInit", archive_write:"phaseArchiveWrite", archive_import:"phaseArchiveImport", analytics_rebuild:"phaseAnalyticsRebuild", validation:"phaseValidation", history_read:"phaseHistoryRead", history_export:"phaseHistoryExport", history_export_complete:"phaseHistoryExportComplete", complete:"phaseComplete", reset:"phaseReset", native_ready:"phaseNativeReady", native_scan:"phaseNativeScan", native_parse:"phaseNativeParse", native_merge:"phaseNativeMerge", native_analytics:"phaseNativeAnalytics", native_snapshot:"phaseNativeSnapshot" };
const safe = (rows) => Array.isArray(rows) ? rows : [];
const newestFirst = (rows) => safe(rows).slice().sort((a, b) => String(b?.startedAtUtc || b?.date || "").localeCompare(String(a?.startedAtUtc || a?.date || "")));
const sum = (rows, field) => safe(rows).reduce((total, row) => total + (Number(row?.[field]) || 0), 0);
const maximum = (rows, field) => { const values = safe(rows).map((row)=>Number(row?.[field])).filter(Number.isFinite); return values.length ? Math.max(...values) : null; };
const median = (values) => { const rows = safe(values).map(Number).filter(Number.isFinite).sort((a,b)=>a-b); if (!rows.length) return null; const middle = Math.floor(rows.length / 2); return rows.length % 2 ? rows[middle] : (rows[middle - 1] + rows[middle]) / 2; };
const num = (value, locale, digits = 1) => value == null || !Number.isFinite(Number(value)) ? "—" : new Intl.NumberFormat(locale, { maximumFractionDigits: digits }).format(Number(value));
const dateText = (value, locale) => value ? new Intl.DateTimeFormat(locale, { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value)) : "—";
const timeText = (value, locale) => value ? new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit" }).format(new Date(value)) : "—";
const duration = (minutes, t) => minutes == null ? "—" : minutes >= 60 ? `${Math.floor(minutes / 60)} ${t("hourShort")} ${Math.round(minutes % 60)} ${t("minuteShort")}` : `${Math.round(minutes)} ${t("minuteShort")}`;

function Icon({ name }) { return <svg className="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d={iconPaths[name]} /></svg>; }
function inPeriod(date, period, maxDate, customRange) { const value = String(date || "").slice(0,10); if (!value) return false; if (period === "all") return true; if (period === "custom") { const first = customRange?.start && customRange?.end && customRange.start > customRange.end ? customRange.end : customRange?.start; const last = customRange?.start && customRange?.end && customRange.start > customRange.end ? customRange.start : customRange?.end; return (!first || value >= first) && (!last || value <= last); } const boundary = new Date(`${maxDate}T00:00:00Z`); boundary.setUTCDate(boundary.getUTCDate() - Number(period) + 1); return value >= boundary.toISOString().slice(0, 10) && value <= maxDate; }
function PeriodBar({ period, setPeriod, customRange, setCustomRange, minDate, maxDate, t }) { const update=(field)=>(event)=>{const value=event.currentTarget.value;setCustomRange((current)=>({...current,[field]:value}));}; return <div className="period-bar"><span>{t("period")}</span>{[["7",t("sevenDays")],["15",t("fifteenDays")],["30",t("thirtyDays")],["all",t("allData")],["custom",t("customPeriod")]].map(([value,label])=><button key={value} className={period===value?"is-active":""} onClick={()=>setPeriod(value)}>{label}</button>)}{period==="custom"?<div className="custom-period"><label>{t("startDate")}<input type="date" min={minDate} max={maxDate} value={customRange.start} onInput={update("start")} onChange={update("start")}/></label><span>—</span><label>{t("endDate")}<input type="date" min={minDate} max={maxDate} value={customRange.end} onInput={update("end")} onChange={update("end")}/></label></div>:null}</div>; }
function Tip({ locale, suffix = "" }) { return <Tooltip contentStyle={{ borderRadius: 10, border: "1px solid var(--line)", background: "var(--panel)", color: "var(--ink)", fontSize: 12, boxShadow: "var(--shadow)" }} formatter={(value, name) => [`${num(value, locale, 2)}${suffix}`, name]} />; }
function Chart({ children, height = 285 }) { return <div className="chart-wrap" style={{ height }}><ResponsiveContainer width="100%" height="100%">{children}</ResponsiveContainer></div>; }
function Metric({ label, value, unit, note, tone = "" }) { return <article className={`dash-metric ${tone ? `tone-${tone}` : ""}`}><span>{label}</span><strong>{value}{unit ? <small>{unit}</small> : null}</strong>{note ? <em>{note}</em> : null}</article>; }
function Panel({ title, subtitle, action, children }) { return <section className="dash-panel"><header><div><h3>{title}</h3>{subtitle ? <p>{subtitle}</p> : null}</div>{action}</header>{children}</section>; }
function Empty({ t }) { return <div className="section-empty"><strong>{t("noResults")}</strong><p>{t("changePeriod")}</p></div>; }
function ChartEmpty({ t, message }) { return <div className="chart-empty-state"><strong>{t("noChartData")}</strong><p>{message || t("noChartDataHelp")}</p></div>; }

function Overview({ data, locale, t, period, maxDate, customRange, openSection }) {
  const daily = safe(data.daily).filter((row) => inPeriod(row.date, period, maxDate, customRange));
  const trips = safe(data.trips).filter((row) => inPeriod(row.date, period, maxDate, customRange));
  const journeys = newestFirst(safe(data.journeys).filter((row) => inPeriod(row.date, period, maxDate, customRange)));
  const charges = newestFirst(safe(data.charges).filter((row) => inPeriod(row.date, period, maxDate, customRange)));
  const distance = sum(daily, "distanceKm"), net = sum(daily, "netEnergyKwh"), wall = sum(charges, "wallEnergyKwh"), battery = sum(charges, "batteryEnergyKwh");
  const chart = daily.slice(-30).map((row) => ({ ...row, label: row.date?.slice(5) }));
  return <><div className="metric-grid overview-metrics"><Metric tone="mint" label={t("distance")} value={num(distance, locale)} unit=" km" note={`${journeys.length} ${t("journeysLower")}`} /><Metric tone="cyan" label={t("averageConsumption")} value={num(distance ? net / distance * 100 : null, locale)} unit=" kWh/100" note={`${num(sum(daily, "regeneratedKwh"), locale)} kWh ${t("regeneratedLower")}`} /><Metric tone="violet" label={t("drivingTime")} value={num(sum(daily, "drivingHours"), locale)} unit={` ${t("hourShort")}`} note={`${trips.length} ${t("tripsLower")}`} /><Metric tone="amber" label={t("chargedEnergy")} value={num(battery, locale)} unit=" kWh" note={`${charges.length} ${t("chargesLower")}`} /><Metric tone="coral" label={t("chargeEfficiency")} value={num(wall ? battery / wall * 100 : null, locale)} unit="%" note={`${num(wall, locale)} kWh ${t("fromGrid")}`} /></div>
    <div className="dashboard-grid two"><Panel title={t("dailyDistance")} subtitle={t("lastDaysInPeriod")}><Chart><BarChart data={chart} margin={{ top: 18, right: 12, left: -16 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tip locale={locale} suffix=" km" /><Bar dataKey="distanceKm" name={t("distance")} fill={C.mint} radius={[5, 5, 0, 0]} maxBarSize={28} /></BarChart></Chart></Panel><Panel title={t("energyTrend")} subtitle={t("netVsRegenerated")}><Chart><ComposedChart data={chart} margin={{ top: 18, right: 12, left: -14 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tip locale={locale} /><Legend wrapperStyle={{ fontSize: 11 }} /><Area type="monotone" dataKey="netEnergyKwh" name={t("netEnergy")} stroke={C.teal} fill="rgba(58,181,174,.14)" /><Line type="monotone" dataKey="regeneratedKwh" name={t("regenerated")} stroke={C.amber} dot={false} strokeWidth={2} /></ComposedChart></Chart></Panel></div>
    <div className="dashboard-grid two"><Panel title={t("recentJourneys")} action={<button className="text-action" onClick={() => openSection("journeys")}>{t("viewAll")}</button>}><div className="compact-records">{journeys.slice(0,5).map((row) => <div key={row.journeyId}><span><strong>{dateText(row.startedAtUtc, locale)}</strong><small>{timeText(row.startedAtUtc, locale)} · {duration(row.durationMinutes, t)}</small></span><span><strong>{num(row.distanceKm, locale)} km</strong><small>{num(row.consumptionKwh100, locale)} kWh/100</small></span></div>)}</div></Panel><Panel title={t("recentCharges")} action={<button className="text-action" onClick={() => openSection("charging")}>{t("viewAll")}</button>}><div className="compact-records">{charges.slice(0,5).map((row) => <div key={row.chargeId}><span><strong>{dateText(row.startedAtUtc, locale)}</strong><small>{row.chargeType} · {duration(row.durationMinutes, t)}</small></span><span><strong>{num(row.batteryEnergyKwh, locale)} kWh</strong><small>{num(row.socStartPct, locale, 0)} → {num(row.socEndPct, locale, 0)}%</small></span></div>)}</div></Panel></div></>;
}

function JourneyDetail({ selected, trips, locale, t }) {
  const segments = safe(selected.tripIds).map((id) => trips.find((row) => row.tripId === id)).filter(Boolean);
  const series = segments.flatMap((trip, segment) => safe(trip.series).map((point) => ({ ...point, elapsed: segment * 1000 + Number(point.elapsedMinutes || 0) })));
  const maxOf = (field) => maximum(segments, field);
  return <div className="detail-stack"><Panel title={`${dateText(selected.startedAtUtc, locale)} · ${timeText(selected.startedAtUtc, locale)}`} subtitle={`${duration(selected.durationMinutes, t)} · ${segments.length} ${t("segmentsLower")}`}><div className="metric-grid detail-metrics"><Metric label={t("distance")} value={num(selected.distanceKm, locale)} unit=" km" /><Metric label={t("consumption")} value={num(selected.consumptionKwh100, locale)} unit=" kWh/100" /><Metric label={t("netEnergy")} value={num(selected.netEnergyKwh, locale)} unit=" kWh" /><Metric label={t("regenerated")} value={num(selected.regeneratedKwh, locale)} unit=" kWh" note={`${num(selected.regenerationSharePct,locale)}% ${t("grossEnergy")}`} /><Metric label={t("maximumSpeed")} value={num(selected.maxSpeedKmh, locale)} unit=" km/h" /></div></Panel>
    {segments.some((row)=>row.peakDrivePowerKw!=null)?<Panel title={t("technicalHighlights")} subtitle={t("technicalHighlightsHelp")}><div className="metric-grid detail-metrics"><Metric label={t("peakDrivePower")} value={num(maxOf("peakDrivePowerKw"),locale)} unit=" kW"/><Metric label={t("peakRegeneration")} value={num(maxOf("peakRegenPowerKw"),locale)} unit=" kW"/><Metric label={t("maximumAcceleration")} value={num(maxOf("maxAccelerationG"),locale,2)} unit=" g"/><Metric label={t("maximumBraking")} value={num(maxOf("maxBrakingG"),locale,2)} unit=" g"/><Metric label={t("rearMotorSpeed")} value={num(maxOf("maxRearMotorRpm"),locale,0)} unit=" rpm"/><Metric label={t("tyrePressureRange")} value={`${num(Math.min(...segments.map((row)=>row.tyrePressureMinKpa).filter(Number.isFinite)),locale)}–${num(maxOf("tyrePressureMaxKpa"),locale)}`} unit=" kPa"/></div></Panel>:null}
    <div className="dashboard-grid two technical-grid"><Panel title={t("speedProfile")} subtitle={t("speedProfileHelp")}><Chart><LineChart data={series} margin={{ top: 15, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsed" hide /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tip locale={locale} /><Line type="monotone" dataKey="speedKmh" name={`${t("speed")} km/h`} stroke={C.teal} dot={false} strokeWidth={2} /><Line type="monotone" dataKey="speedPeakKmh" name={t("peak")} stroke={C.cyan} dot={false} /></LineChart></Chart></Panel><Panel title={t("powerProfile")} subtitle={t("powerProfileHelp")}><Chart><AreaChart data={series} margin={{ top: 15, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsed" hide /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} axisLine={false} tickLine={false} /><ReferenceLine y={0} stroke="var(--muted)" /><Tip locale={locale} /><Area type="monotone" dataKey="powerKw" name={`${t("power")} kW`} stroke={C.amber} fill="rgba(227,166,47,.18)" /></AreaChart></Chart></Panel><Panel title={t("socAndRange")} subtitle={t("socAndRangeHelp")}><Chart><LineChart data={series} margin={{ top: 15, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsed" hide /><YAxis yAxisId="a" tick={{ fill: "var(--muted)", fontSize: 10 }} /><YAxis yAxisId="b" orientation="right" tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Legend wrapperStyle={{ fontSize: 11 }} /><Line yAxisId="a" type="monotone" dataKey="socPct" name="SOC %" stroke={C.mint} dot={false} strokeWidth={2} /><Line yAxisId="b" type="monotone" dataKey="displayedRangeKm" name={t("displayedRange")} stroke={C.violet} dot={false} strokeWidth={2} /></LineChart></Chart></Panel><Panel title={t("temperatureProfile")} subtitle={t("temperatureProfileHelp")}><Chart><LineChart data={series} margin={{ top: 15, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsed" hide /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Line type="monotone" dataKey="batteryTempC" name={t("batteryTemperature")} stroke={C.coral} dot={false} strokeWidth={2} /></LineChart></Chart></Panel></div>
    <Panel title={t("journeyStructure")} subtitle={t("journeyStructureHelp")}><div className="detail-table">{segments.map((row, index) => <div key={row.tripId}><span className="segment-number">{index + 1}</span><strong>{timeText(row.startedAtUtc, locale)}</strong><span>{num(row.distanceKm, locale)} km</span><span>{duration(row.durationMinutes, t)}</span><span>{num(row.consumptionKwh100, locale)} kWh/100</span><span>{num(row.socStartPct, locale, 0)} → {num(row.socEndPct, locale, 0)}%</span></div>)}</div></Panel></div>;
}

function Journeys({ data, locale, t, period, maxDate, customRange }) {
  const rows = newestFirst(safe(data.journeys).filter((row) => inPeriod(row.date, period, maxDate, customRange)));
  const [selectedId, setSelectedId] = useState(null), [query, setQuery] = useState("");
  const visible = rows.filter((row) => `${row.date} ${row.distanceKm}`.toLowerCase().includes(query.toLowerCase()));
  const selected = visible.find((row) => row.journeyId === selectedId) ?? visible[0];
  if (!selected) return <Empty t={t} />;
  return <><div className="list-toolbar"><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("searchJourneys")} /><span>{visible.length} {t("journeysLower")}</span></div><div className="master-detail"><Panel title={t("journeyList")}><div className="record-list">{visible.map((row) => <button key={row.journeyId} className={`record-button ${row.journeyId === selected.journeyId ? "is-active" : ""}`} onClick={() => setSelectedId(row.journeyId)}><span><strong>{dateText(row.startedAtUtc, locale)}</strong><small>{timeText(row.startedAtUtc, locale)} · {safe(row.tripIds).length} {t("segmentsLower")}</small></span><span><strong>{num(row.distanceKm, locale)} km</strong><small>{num(row.consumptionKwh100, locale)} kWh/100</small></span></button>)}</div></Panel><JourneyDetail selected={selected} trips={safe(data.trips)} locale={locale} t={t} /></div></>;
}

function Driving({ data, locale, t, period, maxDate, customRange }) {
  const filter = (row) => inPeriod(row.date,period,maxDate,customRange);
  const trips=safe(data.trips).filter(filter), speed=safe(data.driving?.speed).filter(filter), pedal=safe(data.driving?.pedal).filter(filter), gg=safe(data.driving?.gg).filter(filter), events=safe(data.driving?.events).filter(filter);
  const aggregate=(rows)=>[...rows.reduce((map,row)=>map.set(row.band,(map.get(row.band)||0)+Number(row.seconds||0)),new Map())].map(([band,seconds])=>({band,minutes:seconds/60}));
  const speedRows=aggregate(speed), pedalRows=aggregate(pedal), drivingMinutes=speedRows.reduce((total,row)=>total+row.minutes,0), regenerated=sum(trips,"regeneratedKwh"), used=sum(trips,"energyUsedKwh"), fast=speedRows.filter((row)=>row.band.startsWith("120")||row.band.startsWith("150")).reduce((total,row)=>total+row.minutes,0);
  const peak=(kind)=>maximum(events.filter((row)=>row.kind===kind),"valueG");
  if(!trips.length)return <Empty t={t}/>;
  return <><div className="metric-grid activity-metrics"><Metric tone="mint" label={t("regeneratedEnergy")} value={num(regenerated,locale)} unit=" kWh" note={`${num(used+regenerated?regenerated/(used+regenerated)*100:null,locale)}% ${t("grossEnergy")}`}/><Metric tone="cyan" label={t("movingTime")} value={duration(drivingMinutes,t)} note={`${trips.length} ${t("segmentsLower")}`}/><Metric label={t("maximumAcceleration")} value={num(peak("acceleration"),locale,2)} unit=" g"/><Metric tone="amber" label={t("maximumBraking")} value={num(peak("braking"),locale,2)} unit=" g"/><Metric tone="violet" label={t("timeAbove120")} value={duration(fast,t)} note={`${num(drivingMinutes?fast/drivingMinutes*100:null,locale)}%`}/></div>
    <div className="method-note"><strong>{t("observationalMetrics")}</strong><p>{t("drivingDisclaimer")}</p></div>
    <div className="dashboard-grid two"><Panel title={t("speedDistribution")} subtitle={t("speedDistributionHelp")}><Chart><BarChart data={speedRows} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="band" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix={` ${t("minuteShort")}`}/><Bar dataKey="minutes" fill={C.mint} radius={[4,4,0,0]}/></BarChart></Chart></Panel><Panel title={t("acceleratorUse")} subtitle={t("acceleratorUseHelp")}><Chart><BarChart data={pedalRows} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="band" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix={` ${t("minuteShort")}`}/><Bar dataKey="minutes" fill={C.cyan} radius={[4,4,0,0]}/></BarChart></Chart></Panel><Panel title={t("ggDiagram")} subtitle={t("ggDiagramHelp")}><Chart><ScatterChart margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)"/><XAxis type="number" dataKey="lateralG" name={t("lateralAcceleration")} unit=" g" tick={{fill:"var(--muted)",fontSize:10}}/><YAxis type="number" dataKey="longitudinalG" name={t("longitudinalAcceleration")} unit=" g" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Scatter data={gg} fill={C.violet}/></ScatterChart></Chart></Panel><Panel title={t("dynamicEvents")} subtitle={t("dynamicEventsHelp")}><div className="compact-records">{events.sort((a,b)=>b.valueG-a.valueG).slice(0,12).map((row,index)=><div key={`${row.timestampUtc}-${index}`}><span><strong>{t(`event_${row.kind}`)}</strong><small>{dateText(row.timestampUtc,locale)} · {timeText(row.timestampUtc,locale)}</small></span><span><strong>{num(row.valueG,locale,2)} g</strong><small>{num(row.speedKmh,locale)} km/h</small></span></div>)}</div></Panel></div></>;
}

function ChargeTechnicalSummary({ selected, locale, t }) {
  const rangeAdded = Number.isFinite(Number(selected.rangeStartKm)) && Number.isFinite(Number(selected.rangeEndKm)) ? Number(selected.rangeEndKm) - Number(selected.rangeStartKm) : null;
  return <Panel title={t("chargingTechnicalDetails")} subtitle={t("chargingTechnicalDetailsHelp")}><div className="metric-grid detail-metrics"><Metric label={t("voltageRange")} value={`${num(selected.voltageMinV,locale)}–${num(selected.voltageMaxV,locale)}`} unit=" V"/><Metric label={t("peakCurrent")} value={num(selected.peakCurrentA,locale)} unit=" A"/><Metric label={t("batteryTemperatureRange")} value={`${num(selected.batteryTempStartC,locale)}–${num(selected.batteryTempMaxC,locale)}`} unit=" °C"/><Metric label={t("displayedRangeAdded")} value={num(rangeAdded,locale)} unit=" km"/><Metric label={t("cellTemperaturePositions")} value={`${num(selected.coldestCellIndex,locale,0)} / ${num(selected.hottestCellIndex,locale,0)}`} note={t("coldestHottest")}/><Metric label={t("odometer")} value={num(selected.odometerKm,locale,0)} unit=" km"/></div></Panel>;
}

function Charging({ data, locale, t, period, maxDate, customRange }) {
  const rows = newestFirst(safe(data.charges).filter((row) => inPeriod(row.date, period, maxDate, customRange))); const [selectedId, setSelectedId] = useState(null); const selected = rows.find((row) => row.chargeId === selectedId) ?? rows[0]; if (!selected) return <Empty t={t} />;
  const summary = rows.slice().reverse().map((row) => ({ ...row, label: row.date?.slice(5) })), series = safe(selected.series);
  const hourCounts=rows.reduce((map,row)=>{const hour=Number(new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/Lisbon",hour:"2-digit",hour12:false}).format(new Date(row.startedAtUtc)))%24;map.set(hour,(map.get(hour)||0)+1);return map;},new Map()), common=[...hourCounts].sort((a,b)=>b[1]-a[1])[0], hourShare=common?common[1]/rows.length:0;
  const limitCounts=rows.filter((row)=>(row.socEndPct??100)<99&&((row.socEndPct??0)-(row.socStartPct??0))>=5).reduce((map,row)=>{const value=Math.round(row.socEndPct);map.set(value,(map.get(value)||0)+1);return map;},new Map()), recurring=[...limitCounts].filter(([,count])=>count>=3).sort((a,b)=>b[1]-a[1])[0], typicalGain=median(rows.map((row)=>(row.socEndPct??0)-(row.socStartPct??0)));
  return <><div className="metric-grid charging-metrics"><Metric tone="mint" label={t("chargedEnergy")} value={num(sum(rows, "batteryEnergyKwh"), locale)} unit=" kWh" note={`${rows.length} ${t("chargesLower")}`} /><Metric tone="cyan" label={t("gridEnergy")} value={num(sum(rows, "wallEnergyKwh"), locale)} unit=" kWh" /><Metric tone="amber" label={t("chargeEfficiency")} value={num(sum(rows, "wallEnergyKwh") ? sum(rows, "batteryEnergyKwh") / sum(rows, "wallEnergyKwh") * 100 : null, locale)} unit="%" /><Metric tone="violet" label={t("totalChargingTime")} value={duration(sum(rows,"durationMinutes"),t)} /><Metric label={t("maximumPower")} value={num(maximum(rows,"maxPowerKw"),locale)} unit=" kW" /><Metric tone="coral" label={t("losses")} value={num(sum(rows, "lossKwh"), locale)} unit=" kWh" note={t("totalEstimatedLosses")} /></div>
    <Panel title={t("chargingHabits")} subtitle={t("chargingHabitsHelp")}><div className="metric-grid detail-metrics"><Metric tone="mint" label={t("mostCommonHour")} value={common?`${String(common[0]).padStart(2,"0")}:00`:"—"} note={common?`${common[1]} ${t("ofLower")} ${rows.length} ${t("chargesLower")}`:null}/><Metric label={t("possibleSchedule")} value={common&&common[1]>=3&&hourShare>=.35?`${String(common[0]).padStart(2,"0")}:00`:t("noStrongPattern")} note={`${num(hourShare*100,locale)}% ${t("ofSample")}`}/><Metric tone="amber" label={t("recurringLimit")} value={recurring?`${recurring[0]}%`:t("noStrongPattern")} note={recurring?`${recurring[1]} ${t("sessionsLower")}`:t("minimumThreeSessions")}/><Metric label={t("typicalSocGain")} value={num(typicalGain,locale)} unit=" pp" note={`${rows.length} ${t("sessionsLower")}`}/></div></Panel>
    <div className="dashboard-grid two"><Panel title={t("energyByCharge")}><Chart><BarChart data={summary} margin={{ top: 15, right: 10, left: -14 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "var(--muted)", fontSize: 9 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Legend wrapperStyle={{ fontSize: 11 }} /><Bar dataKey="batteryEnergyKwh" name={t("batteryEnergy")} fill={C.mint} radius={[4,4,0,0]} /><Bar dataKey="lossKwh" name={t("losses")} fill={C.coral} radius={[4,4,0,0]} /></BarChart></Chart></Panel><Panel title={t("efficiencyTrend")}><Chart><LineChart data={summary} margin={{ top: 15, right: 10, left: -14 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "var(--muted)", fontSize: 9 }} /><YAxis domain={[0,100]} tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} suffix="%" /><Line dataKey="efficiencyPct" name={t("efficiency")} stroke={C.amber} dot={{ r: 3 }} strokeWidth={2} /></LineChart></Chart></Panel></div>
    <div className="master-detail"><Panel title={t("chargeList")}><div className="record-list">{rows.map((row) => <button key={row.chargeId} className={`record-button ${row.chargeId === selected.chargeId ? "is-active" : ""}`} onClick={() => setSelectedId(row.chargeId)}><span><strong>{dateText(row.startedAtUtc, locale)}</strong><small>{timeText(row.startedAtUtc, locale)} · {row.chargeType}</small></span><span><strong>{num(row.batteryEnergyKwh, locale)} kWh</strong><small>{num(row.socStartPct, locale, 0)} → {num(row.socEndPct, locale, 0)}%</small></span></button>)}</div></Panel><div className="detail-stack"><Panel title={`${dateText(selected.startedAtUtc, locale)} · ${timeText(selected.startedAtUtc, locale)}`} subtitle={`${selected.chargeType} · ${duration(selected.durationMinutes, t)}`}><div className="metric-grid detail-metrics"><Metric label={t("batteryEnergy")} value={num(selected.batteryEnergyKwh, locale)} unit=" kWh" /><Metric label={t("gridEnergy")} value={num(selected.wallEnergyKwh, locale)} unit=" kWh" /><Metric label={t("efficiency")} value={num(selected.efficiencyPct, locale)} unit="%" /><Metric label={t("maximumPower")} value={num(selected.maxPowerKw, locale)} unit=" kW" /><Metric label={t("losses")} value={num(selected.lossKwh, locale)} unit=" kWh" /></div></Panel><ChargeTechnicalSummary selected={selected} locale={locale} t={t}/><div className="dashboard-grid two technical-grid"><Panel title={t("chargeCurve")} subtitle={t("powerAndSoc")}><Chart><LineChart data={series} margin={{ top: 12, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsedMinutes" tick={{ fill: "var(--muted)", fontSize: 9 }} /><YAxis yAxisId="a" tick={{ fill: "var(--muted)", fontSize: 10 }} /><YAxis yAxisId="b" orientation="right" domain={[0,100]} tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Legend wrapperStyle={{ fontSize: 11 }} /><Line yAxisId="a" dataKey="powerKw" name={t("powerKw")} stroke={C.teal} dot={false} strokeWidth={2} /><Line yAxisId="b" dataKey="socPct" name={t("soc")} stroke={C.amber} dot={false} strokeWidth={2} /></LineChart></Chart></Panel><Panel title={t("voltageCurrent")}><Chart><LineChart data={series} margin={{ top: 12, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsedMinutes" hide /><YAxis yAxisId="a" tick={{ fill: "var(--muted)", fontSize: 10 }} /><YAxis yAxisId="b" orientation="right" tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Legend wrapperStyle={{ fontSize: 11 }} /><Line yAxisId="a" dataKey="voltageV" name={t("voltage")} stroke={C.violet} dot={false} /><Line yAxisId="b" dataKey="currentA" name={t("current")} stroke={C.cyan} dot={false} /></LineChart></Chart></Panel><Panel title={t("temperatureProfile")}><Chart><LineChart data={series} margin={{ top: 12, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsedMinutes" tick={{ fill: "var(--muted)", fontSize: 9 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Line dataKey="batteryTempC" name={t("batteryTemperature")} stroke={C.coral} dot={false} strokeWidth={2} /></LineChart></Chart></Panel><Panel title={t("powerPeakProfile")}><Chart><LineChart data={series} margin={{ top: 12, right: 12, left: -12 }}><CartesianGrid stroke="var(--grid)" vertical={false} /><XAxis dataKey="elapsedMinutes" tick={{ fill: "var(--muted)", fontSize: 9 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 10 }} /><Tip locale={locale} /><Line dataKey="powerPeakKw" name={t("peakPower")} stroke={C.amber} dot={false} strokeWidth={2} /></LineChart></Chart></Panel></div></div></div></>;
}

function Battery({ data, locale, t, period, maxDate, customRange }) {
  const battery = data.battery || {};
  const daily = safe(data.daily).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const charges = safe(data.charges).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const history = safe(battery.history).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const parking = safe(battery.parking).filter((row)=>inPeriod(row.startedAtUtc,period,maxDate,customRange));
  const capacity = median(history.map((row)=>row.capacityKwh));
  const distance = sum(daily,"distanceKm"), consumption = distance ? sum(daily,"netEnergyKwh") / distance * 100 : null;
  const range100 = capacity && consumption ? capacity / consumption * 100 : null, range70 = range100 == null ? null : range100 * .7;
  const observedSeconds = sum(parking,"observedSeconds"), parkedEnergy = sum(parking,"energyKwh");
  const parkedWatts = observedSeconds ? parkedEnergy / (observedSeconds / 3600) * 1000 : null;
  const longParking = parking.filter((row)=>Number(row.durationHours)>=6 && Number.isFinite(Number(row.socLossPerDay)));
  const parkedLoss = median(longParking.map((row)=>row.socLossPerDay));
  const parkedLossHour = parkedLoss == null ? null : parkedLoss / 24;
  const parkedRangeLoss = capacity && consumption && parkedLoss != null ? capacity * parkedLoss / consumption : null;
  const temp = charges.filter((row)=>row.batteryTempMaxC!=null && row.efficiencyPct!=null).map((row)=>({temperature:row.batteryTempMaxC,efficiency:row.efficiencyPct}));
  const parkedPowerChart = parking.filter((row)=>Number.isFinite(Number(row.averageWatts))).slice(0,40).reverse();
  const parkedLossChart = longParking.slice(0,40).reverse();
  const batteryDaily=safe(battery.daily).filter((row)=>inPeriod(row.date,period,maxDate,customRange)).map((row)=>({...row,label:row.date?.slice(5)}));
  const rangeSamples=safe(battery.rangeSamples).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const tyres=safe(battery.tyres).filter((row)=>inPeriod(row.date,period,maxDate,customRange)).map((row)=>({...row,label:row.date?.slice(5)}));
  const xpengRange=median(rangeSamples.map((row)=>row.impliedFullRangeKm)), latestTyre=tyres.at(-1), firstTyre=tyres[0], tyreDrift=latestTyre&&firstTyre?latestTyre.averageKpa-firstTyre.averageKpa:null;
  return <>
    <div className="metric-grid battery-metrics"><Metric tone="mint" label={t("realRange100")} value={num(range100,locale)} unit=" km" note={`${num(consumption,locale)} kWh/100 km ${t("inPeriodLower")}`} /><Metric label={t("range80to10")} value={num(range70,locale)} unit=" km" note={t("usableWindow70")} /><Metric label={t("estimatedCapacity")} value={num(capacity,locale)} unit=" kWh" note={`${history.length} ${t("qualifiedChargesLower")}`} /><Metric tone="amber" label={t("relativeSoh")} value={num(history.at(-1)?.relativeSohPct,locale)} unit="%" note={t("notBmsReading")} /><Metric label={t("parkedObservedDraw")} value={num(parkedWatts,locale)} unit=" W" note={`${num(parkedEnergy,locale)} kWh ${t("measuredWhileParked")}`} /><Metric label={t("parkedLossPerDay")} value={num(parkedLoss,locale,2)} unit={`%/${t("dayShort")}`} note={`${num(parkedLossHour,locale,2)}%/h · ${num(parkedRangeLoss,locale)} km/${t("dayShort")}`} /></div>
    <div className="method-note"><strong>{t("calculatedMetrics")}</strong><p>{t("calculatedMetricsHelp")}</p></div>
    <div className="metric-grid battery-metrics"><Metric tone="cyan" label={t("xpengPredictedRange100")} value={num(xpengRange,locale)} unit=" km" note={`${rangeSamples.length} ${t("eligibleSamples")}`}/><Metric tone="mint" label={t("currentAveragePressure")} value={num(latestTyre?.averageKpa,locale)} unit=" kPa"/><Metric label={t("pressureChange")} value={num(tyreDrift,locale)} unit=" kPa" note={t("fourTyreMedian")}/><Metric tone="amber" label={t("maximumTyreImbalance")} value={num(maximum(tyres.flatMap((row)=>[{value:row.frontImbalanceKpa},{value:row.rearImbalanceKpa}]),"value"),locale)} unit=" kPa"/></div>
    <div className="dashboard-grid two"><Panel title={t("socBand")} subtitle={t("socBandHelp")}>{batteryDaily.length?<Chart><AreaChart data={batteryDaily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis domain={[0,100]} unit="%" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Legend wrapperStyle={{fontSize:11}}/><Area dataKey="socMaxPct" name={t("maximumSoc")} stroke={C.mint} fill="rgba(32,169,131,.20)"/><Area dataKey="socMinPct" name={t("minimumSoc")} stroke={C.amber} fill="var(--panel)"/></AreaChart></Chart>:<ChartEmpty t={t}/>}</Panel><Panel title={t("thermalSpread")} subtitle={t("thermalSpreadHelp")}>{batteryDaily.length?<Chart><ComposedChart data={batteryDaily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis unit=" °C" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Legend wrapperStyle={{fontSize:11}}/><Line dataKey="batteryTempMaxC" name={t("maximumTemperature")} stroke={C.coral} dot={false}/><Line dataKey="batteryTempMinC" name={t("minimumTemperature")} stroke={C.cyan} dot={false}/><Bar dataKey="temperatureSpreadMaxC" name={t("spread")} fill={C.amber}/></ComposedChart></Chart>:<ChartEmpty t={t}/>}</Panel><Panel title={t("xpengRangeTrend")} subtitle={t("xpengRangeTrendHelp")}>{batteryDaily.some((row)=>row.impliedRangeMedianKm!=null)?<Chart><LineChart data={batteryDaily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis unit=" km" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Line dataKey="impliedRangeMedianKm" name={t("xpengPredictedRange100")} stroke={C.violet} dot={{r:2}} strokeWidth={2}/></LineChart></Chart>:<ChartEmpty t={t}/>}</Panel><Panel title={t("tyrePressureTrend")} subtitle={t("tyrePressureTrendHelp")}>{tyres.length?<Chart><LineChart data={tyres} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis unit=" kPa" domain={["dataMin - 5","dataMax + 5"]} tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Legend wrapperStyle={{fontSize:11}}/><Line dataKey="frontLeftKpa" name="FL" stroke={C.mint} dot={false}/><Line dataKey="frontRightKpa" name="FR" stroke={C.cyan} dot={false}/><Line dataKey="rearLeftKpa" name="RL" stroke={C.amber} dot={false}/><Line dataKey="rearRightKpa" name="RR" stroke={C.coral} dot={false}/></LineChart></Chart>:<ChartEmpty t={t}/>}</Panel></div>
    <div className="dashboard-grid two"><Panel title={t("capacityAndSoh")} subtitle={t("notBmsSoh")}>{history.length?<Chart height={320}><LineChart data={history} margin={{top:16,right:18,left:-8}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="date" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis yAxisId="a" tick={{fill:"var(--muted)",fontSize:10}}/><YAxis yAxisId="b" orientation="right" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Legend wrapperStyle={{fontSize:11}}/><Line yAxisId="a" dataKey="rollingCapacityKwh" name={t("rollingCapacity")} stroke={C.mint} dot={{r:3}} strokeWidth={2}/><Line yAxisId="b" dataKey="relativeSohPct" name={t("relativeSoh")} stroke={C.amber} dot={false} strokeWidth={2}/></LineChart></Chart>:<ChartEmpty t={t}/>}</Panel><Panel title={t("thermalEfficiency")} subtitle={t("thermalEfficiencyHelp")}>{temp.length?<Chart height={320}><ScatterChart margin={{top:16,right:18,left:-8}}><CartesianGrid stroke="var(--grid)"/><XAxis type="number" dataKey="temperature" name={t("temperature")} unit="°C" tick={{fill:"var(--muted)",fontSize:10}}/><YAxis type="number" dataKey="efficiency" name={t("efficiency")} unit="%" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Scatter data={temp} fill={C.cyan}>{temp.map((_,index)=><Cell key={index} fill={index%2?C.cyan:C.teal}/>)}</Scatter></ScatterChart></Chart>:<ChartEmpty t={t}/>}</Panel></div>
    <div className="dashboard-grid two"><Panel title={t("energyBalance")} subtitle={t("energyBalanceHelp")}>{charges.length?<Chart><BarChart data={charges.slice(-20)} margin={{top:16,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="date" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Legend wrapperStyle={{fontSize:11}}/><Bar stackId="e" dataKey="batteryEnergyKwh" name={t("batteryEnergy")} fill={C.mint}/><Bar stackId="e" dataKey="lossKwh" name={t("losses")} fill={C.coral}/></BarChart></Chart>:<ChartEmpty t={t}/>}</Panel><Panel title={t("parkedPower")} subtitle={t("parkedPowerHelp")}>{parkedPowerChart.length?<Chart><BarChart data={parkedPowerChart} margin={{top:16,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="startedAtUtc" tickFormatter={(v)=>v?.slice(5,10)} tick={{fill:"var(--muted)",fontSize:9}}/><YAxis unit=" W" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix=" W"/><Bar dataKey="averageWatts" name={t("parkedPower")} fill={C.cyan} radius={[4,4,0,0]}/></BarChart></Chart>:<ChartEmpty t={t}/>}</Panel></div>
    <Panel title={t("parkedBatteryLoss")} subtitle={`${longParking.length} ${t("longIntervals")} · ${num(sum(longParking,"durationHours"),locale)} h ${t("analysedLower")}`}>{parkedLossChart.length?<Chart><BarChart data={parkedLossChart} margin={{top:16,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="startedAtUtc" tickFormatter={(v)=>v?.slice(5,10)} tick={{fill:"var(--muted)",fontSize:9}}/><YAxis unit="%" tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix="%"/><ReferenceLine y={parkedLoss} stroke={C.amber} strokeDasharray="5 4" label={{value:t("median"),fill:"var(--muted)",fontSize:10}}/><Bar dataKey="socLossPerDay" name={t("socLossPerDay")} fill={C.amber} radius={[4,4,0,0]}/></BarChart></Chart>:<ChartEmpty t={t} message={t("noParkingChartData")}/>}</Panel>
    <Panel title={t("parkingIntervals")} subtitle={t("parkingTableHelp")}><div className="data-table parking-table detailed"><div className="table-head"><span>{t("date")}</span><span>{t("duration")}</span><span>{t("socChange")}</span><span>{t("socLoss")}</span><span>{t("socLossPerHour")}</span><span>{t("socLossPerDay")}</span><span>{t("energy")}</span><span>{t("averagePower")}</span><span>{t("coverage")}</span><span>{t("confidence")}</span></div>{parking.slice(0,40).map((row)=><div key={row.stopId}><span>{dateText(row.startedAtUtc,locale)}</span><span>{num(row.durationHours,locale)} h</span><span>{num(row.socStartPct,locale,0)} → {num(row.socEndPct,locale,0)}%</span><span>{num(row.socLossPct,locale,1)}%</span><span>{num(row.socLossPerHour,locale,2)}%</span><span>{num(row.socLossPerDay,locale,2)}%</span><span>{num(row.energyKwh,locale,2)} kWh</span><span>{num(row.averageWatts,locale,0)} W</span><span>{num(row.coveragePct,locale)}%</span><span className={`confidence confidence-${row.confidence}`}>{t(`confidence_${row.confidence}`)}</span></div>)}</div></Panel>
  </>;
}

function DrivingHeatmap({ rows, t }) {
  const labels=[t("mondayShort"),t("tuesdayShort"),t("wednesdayShort"),t("thursdayShort"),t("fridayShort"),t("saturdayShort"),t("sundayShort")], values=new Map();
  rows.forEach((row)=>{const key=`${row.weekdayIndex}|${row.hourIndex}`;values.set(key,(values.get(key)||0)+Number(row.drivingMinutes||0));});
  const maximumValue=Math.max(1,...values.values());
  return <div className="driving-heatmap"><div className="heatmap-hours"><span/>{Array.from({length:24},(_,hour)=><small key={hour}>{hour%3===0?String(hour).padStart(2,"0"):""}</small>)}</div>{labels.map((label,weekday)=><div className="heatmap-row" key={label}><strong>{label}</strong>{Array.from({length:24},(_,hour)=>{const value=values.get(`${weekday}|${hour}`)||0;return <i key={hour} title={`${label} ${String(hour).padStart(2,"0")}:00 · ${Math.round(value)} min`} style={{opacity:value?Math.max(.18,value/maximumValue):.04}}/>;})}</div>)}</div>;
}

function Activity({ data, locale, t, period, maxDate, customRange }) {
  const weekdays = [t("mondayShort"),t("tuesdayShort"),t("wednesdayShort"),t("thursdayShort"),t("fridayShort"),t("saturdayShort"),t("sundayShort")];
  const daily = safe(data.daily).filter((row)=>inPeriod(row.date,period,maxDate,customRange)).map((row)=>({...row,label:row.date?.slice(5)}));
  const trips = safe(data.trips).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const journeys = safe(data.journeys).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const weekdayTotals = Array.from({length:7},()=>({trips:0,distanceKm:0}));
  const hourTotals = Array.from({length:24},(_,hour)=>({hour,trips:0}));
  trips.forEach((row)=>{ const weekday=(new Date(`${row.date}T00:00:00Z`).getUTCDay()+6)%7; weekdayTotals[weekday].trips+=1; weekdayTotals[weekday].distanceKm+=Number(row.distanceKm)||0; const hour=Number(new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/Lisbon",hour:"2-digit",hour12:false}).format(new Date(row.startedAtUtc)))%24; if(Number.isFinite(hour)) hourTotals[hour].trips+=1; });
  const weekday = weekdayTotals.map((row,index)=>({...row,label:weekdays[index]}));
  const hours = hourTotals.map((row)=>({...row,label:`${String(row.hour).padStart(2,"0")}h`}));
  const monthlyMap = new Map(); daily.forEach((row)=>{ const key=row.date.slice(0,7), current=monthlyMap.get(key)||{month:key,distanceKm:0,journeys:0}; current.distanceKm+=Number(row.distanceKm)||0; current.journeys+=Number(row.journeys)||0; monthlyMap.set(key,current); });
  const monthly = [...monthlyMap.values()].map((row)=>({...row,label:row.month}));
  const heatmap=safe(data.activity?.heatmap).filter((row)=>inPeriod(row.date,period,maxDate,customRange));
  const bar = (rows,key,color) => rows.some((row)=>Number(row[key]))?<Chart><BarChart data={rows} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Bar dataKey={key} fill={color} radius={[4,4,0,0]}/></BarChart></Chart>:<ChartEmpty t={t}/>;
  if (!daily.length && !trips.length) return <Empty t={t}/>;
  return <><div className="metric-grid activity-metrics"><Metric tone="mint" label={t("activeDays")} value={num(daily.filter((row)=>row.trips||row.charges).length,locale,0)}/><Metric tone="cyan" label={t("distance")} value={num(sum(daily,"distanceKm"),locale)} unit=" km"/><Metric tone="violet" label={t("drivingTime")} value={num(sum(daily,"drivingHours"),locale)} unit={` ${t("hourShort")}`}/><Metric tone="amber" label={t("journeys")} value={num(journeys.length,locale,0)} note={`${trips.length} ${t("segmentsLower")}`}/></div><Panel title={t("actualMovementHeatmap")} subtitle={t("actualMovementHeatmapHelp")}><DrivingHeatmap rows={heatmap} t={t}/></Panel><div className="dashboard-grid two activity-grid">
    <Panel title={t("dailyEnergy")} subtitle={t("dailyEnergyHelp")}><Chart><BarChart data={daily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix=" kWh"/><Legend wrapperStyle={{fontSize:11}}/><Bar dataKey="energyUsedKwh" name={t("used")} fill={C.amber}/><Bar dataKey="regeneratedKwh" name={t("regenerated")} fill={C.mint}/></BarChart></Chart></Panel>
    <Panel title={t("dailyConsumption")} subtitle={t("dailyConsumptionHelp")}><Chart><LineChart data={daily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale}/><Line dataKey="consumptionKwh100" name="kWh/100 km" stroke={C.coral} dot={{r:2}} strokeWidth={2}/></LineChart></Chart></Panel>
    <Panel title={t("distanceByMonth")}>{bar(monthly,"distanceKm",C.mint)}</Panel><Panel title={t("journeysByMonth")} subtitle={t("journeysByMonthHelp")}>{bar(monthly,"journeys",C.cyan)}</Panel>
    <Panel title={t("weekdayActivity")}>{bar(weekday,"distanceKm",C.violet)}</Panel><Panel title={t("tripStartsByHour")} subtitle={t("localTimeZone")}>{bar(hours,"trips",C.amber)}</Panel>
    <Panel title={t("chargedEnergyPerDay")} subtitle={t("gridVsBattery")}><Chart><BarChart data={daily} margin={{top:12,right:12,left:-12}}><CartesianGrid stroke="var(--grid)" vertical={false}/><XAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:9}}/><YAxis tick={{fill:"var(--muted)",fontSize:10}}/><Tip locale={locale} suffix=" kWh"/><Legend wrapperStyle={{fontSize:11}}/><Bar dataKey="wallEnergyKwh" name={t("gridEnergy")} fill={C.cyan}/><Bar dataKey="batteryEnergyKwh" name={t("batteryEnergy")} fill={C.mint}/></BarChart></Chart></Panel>
    <Panel title={t("chargingSessionsPerDay")}>{bar(daily,"charges",C.teal)}</Panel>
  </div></>;
}

function Report({ data, locale, t, minDate, maxDate }) {
  const [startDate,setStartDate]=useState(minDate), [endDate,setEndDate]=useState(maxDate), [energyPrice,setEnergyPrice]=useState(""), [reference,setReference]=useState(""), [exporting,setExporting]=useState(false), [exportError,setExportError]=useState(false);
  const firstDate=startDate&&endDate&&startDate>endDate?endDate:startDate, lastDate=startDate&&endDate&&startDate>endDate?startDate:endDate;
  const range={start:firstDate,end:lastDate};
  const daily=safe(data.daily).filter((row)=>inPeriod(row.date,"custom",maxDate,range));
  const journeys=safe(data.journeys).filter((row)=>inPeriod(row.date,"custom",maxDate,range));
  const trips=safe(data.trips).filter((row)=>inPeriod(row.date,"custom",maxDate,range));
  const charges=safe(data.charges).filter((row)=>inPeriod(row.date,"custom",maxDate,range));
  const distance=sum(daily,"distanceKm"), netEnergy=sum(daily,"netEnergyKwh"), wallEnergy=sum(charges,"wallEnergyKwh"), batteryEnergy=sum(charges,"batteryEnergyKwh");
  const consumption=distance?netEnergy/distance*100:null, efficiency=wallEnergy?batteryEnergy/wallEnergy*100:null;
  const normalizedPrice=energyPrice.trim()?Number(energyPrice.replace(",",".")):null;
  const hasPrice=normalizedPrice!=null&&Number.isFinite(normalizedPrice)&&normalizedPrice>=0;
  const estimatedCost=hasPrice?wallEnergy*normalizedPrice:null, costPer100=hasPrice&&distance?estimatedCost/distance*100:null;
  const hasRows=daily.length>0||charges.length>0;
  const exportPdf=async()=>{if(!hasRows||exporting)return;setExporting(true);setExportError(false);try{const {downloadReportPdf}=await import("./report-pdf.js");await downloadReportPdf({data,locale,t,startDate,endDate,energyPrice:hasPrice?normalizedPrice:null,reference});}catch(error){console.error(error);setExportError(true);}finally{setExporting(false);}};
  return <div className="report-page">
    <Panel title={t("reportSettings")} subtitle={t("reportSettingsHelp")}>
      <div className="report-form">
        <label><span>{t("startDate")}</span><input type="date" min={minDate} max={maxDate} value={startDate} onChange={(event)=>setStartDate(event.currentTarget.value)}/></label>
        <label><span>{t("endDate")}</span><input type="date" min={minDate} max={maxDate} value={endDate} onChange={(event)=>setEndDate(event.currentTarget.value)}/></label>
        <label><span>{t("reportEnergyPrice")}</span><div className="input-with-unit"><input type="text" inputMode="decimal" placeholder="0,20" value={energyPrice} onChange={(event)=>setEnergyPrice(event.currentTarget.value)}/><small>€/kWh</small></div></label>
        <label><span>{t("reportReference")}</span><input type="text" maxLength="80" placeholder={t("reportReferencePlaceholder")} value={reference} onChange={(event)=>setReference(event.currentTarget.value)}/></label>
        <button className="report-export" type="button" disabled={!hasRows||exporting||(energyPrice.trim()&&!hasPrice)} onClick={exportPdf}><Icon name="report"/><span><strong>{exporting?t("reportGenerating"):t("reportExportPdf")}</strong><small>{t("reportExportHelp")}</small></span></button>
      </div>
      <div className="report-local-note"><strong>{t("privacyTitle")}</strong><span>{t("reportLocalHelp")}</span></div>
      {energyPrice.trim()&&!hasPrice?<div className="report-error">{t("reportInvalidPrice")}</div>:null}
      {exportError?<div className="report-error">{t("reportExportError")}</div>:null}
    </Panel>
    {!hasRows?<Empty t={t}/>:<>
      <div className="report-period"><span>{t("reportPreview")}</span><strong>{dateText(firstDate,locale)} — {dateText(lastDate,locale)}</strong>{reference?<small>{reference}</small>:null}</div>
      <div className="metric-grid report-metrics">
        <Metric tone="mint" label={t("distance")} value={num(distance,locale)} unit=" km" note={`${journeys.length} ${t("journeysLower")}`} />
        <Metric tone="cyan" label={t("averageConsumption")} value={num(consumption,locale)} unit=" kWh/100" note={`${num(sum(daily,"drivingHours"),locale)} ${t("hourShort")}`} />
        <Metric tone="violet" label={t("charges")} value={num(charges.length,locale,0)} note={`${num(wallEnergy,locale)} kWh ${t("fromGrid")}`} />
        <Metric tone="amber" label={t("chargeEfficiency")} value={num(efficiency,locale)} unit="%" note={`${num(sum(charges,"lossKwh"),locale)} kWh ${t("losses").toLowerCase()}`} />
        <Metric label={t("reportEstimatedCost")} value={hasPrice?num(estimatedCost,locale,2):"—"} unit={hasPrice?" €":""} note={hasPrice?`${num(normalizedPrice,locale,2)} €/kWh`:t("reportPriceNeeded")} />
        <Metric tone="coral" label={t("reportCostPer100")} value={hasPrice?num(costPer100,locale,2):"—"} unit={hasPrice?" €":""} note={`${trips.length} ${t("tripsLower")}`} />
      </div>
      <div className="method-note"><strong>{t("reportEstimateTitle")}</strong><p>{t("reportDisclaimer")}</p></div>
      <div className="dashboard-grid two report-tables">
        <Panel title={t("reportDailyBreakdown")} subtitle={t("reportDailyBreakdownHelp")}><div className="report-mini-table"><div className="table-head"><span>{t("date")}</span><span>{t("distance")}</span><span>{t("consumption")}</span><span>{t("gridEnergy")}</span></div>{daily.slice(-14).reverse().map((row)=><div key={row.date}><strong>{dateText(row.date,locale)}</strong><span>{num(row.distanceKm,locale)} km</span><span>{num(row.consumptionKwh100,locale)} kWh/100</span><span>{num(row.wallEnergyKwh,locale)} kWh</span></div>)}</div></Panel>
        <Panel title={t("reportChargingDetails")} subtitle={t("reportChargingDetailsHelp")}><div className="report-mini-table"><div className="table-head"><span>{t("date")}</span><span>{t("chargeType")}</span><span>{t("batteryEnergy")}</span><span>{t("gridEnergy")}</span></div>{charges.slice(-14).reverse().map((row)=><div key={row.chargeId}><strong>{dateText(row.startedAtUtc,locale)}</strong><span>{row.chargeType||"—"}</span><span>{num(row.batteryEnergyKwh,locale)} kWh</span><span>{num(row.wallEnergyKwh,locale)} kWh</span></div>)}</div></Panel>
      </div>
    </>}
  </div>;
}

function Quality({ data, locale, t }) { const coverage = safe(data.quality?.coverage), events = safe(data.quality?.events); return <><div className="quality-summary"><div><span>{t("qualityStatus")}</span><strong>{events.length ? t("reviewRecommended") : t("noCriticalIssues")}</strong><p>{t("qualityStatusHelp")}</p></div><div className="quality-count"><strong>{events.length}</strong><span>{t("qualityEvents")}</span></div></div><div className="metric-grid quality-metrics">{coverage.map((row) => <Metric key={row.family} label={t(`family_${row.family}`)} value={num(row.rows, locale,0)} note={`${dateText(row.firstUtc,locale)} — ${dateText(row.lastUtc,locale)}`} />)}</div><Panel title={t("qualityEvents")} subtitle={t("qualityEventsHelp")}><div className="data-table"><div className="table-head"><span>{t("severity")}</span><span>{t("family")}</span><span>{t("rule")}</span><span>{t("affected")}</span><span>{t("field")}</span></div>{events.map((row,index)=><div key={`${row.rule}-${index}`}><span><i className={`severity severity-${row.severity}`}>{t(`severity_${row.severity}`)}</i></span><span>{t(`family_${row.family}`)}</span><span>{t(`rule_${row.rule}`)}</span><span>{num(row.affectedRows,locale,0)}</span><span>{row.field || "—"}</span></div>)}</div>{!events.length?<div className="inline-success">{t("noQualityEvents")}</div>:null}</Panel><div className="threshold-note"><strong>{t("interpretationRules")}</strong><p>{t("interpretationRulesHelp")}</p></div></>; }

function DataSection({ data, locale, t, busy, onChoose, onChooseHistory, onExport, onReset }) { return <div className="dashboard-grid two data-layout"><Panel title={t("addMoreData")} subtitle={t("addMoreHelp")}><div className="data-actions"><label className={`dashboard-upload ${busy ? "is-disabled" : ""}`}><input type="file" multiple accept=".zip,application/zip" disabled={busy} onChange={(event)=>{onChoose(event.target.files);event.target.value="";}}/><Icon name="data"/><strong>{busy?t("importing"):t("chooseFiles")}</strong><small>{t("dropHint")}</small></label><label className="secondary-action"><input type="file" accept=".xpeng,.json.gz,.gz,application/octet-stream,application/gzip" disabled={busy} onChange={(event)=>{onChooseHistory(event.target.files);event.target.value="";}}/><strong>{t("replaceFromHistory")}</strong></label><button className="primary-action" type="button" disabled={busy} onClick={onExport}>{t("exportHistory")}</button><p className="export-help">{t("exportHistoryHelp")}</p><p className="history-warning">{t("historySensitiveWarning")}</p><button className="danger-link" type="button" disabled={busy} onClick={onReset}>{t("reset")}</button></div></Panel><Panel title={t("importHistory")} subtitle={`${safe(data.imports).length} ${t("filesLower")}`}><div className="import-history">{safe(data.imports).map((row)=><div key={row.sha256}><span><strong>{row.name}</strong><small>{dateText(row.completedAtUtc,locale)} · {num(row.rows,locale,0)} {t("rowsLower")}</small></span><code>{row.sha256?.slice(0,10)}…</code></div>)}</div></Panel></div>; }

export default function Dashboard({ data, locale, setLocale, t, busy, progress, error, onChoose, onChooseHistory, onExport, onReset, onCancel, canCancel, theme, onToggleTheme }) {
  const [section,setSection]=useState("overview"), [period,setPeriod]=useState("all");
  const availableDates=[...safe(data.daily).map((row)=>row.date),...safe(data.trips).map((row)=>row.date),...safe(data.journeys).map((row)=>row.date),...safe(data.charges).map((row)=>row.date),...safe(data.battery?.history).map((row)=>row.date),...safe(data.battery?.parking).map((row)=>String(row.startedAtUtc||"").slice(0,10))].filter(Boolean).sort();
  const minDate=availableDates.at(0)??"", maxDate=availableDates.at(-1)??new Date().toISOString().slice(0,10);
  const [customRange,setCustomRange]=useState(()=>({start:minDate,end:maxDate}));
  const shared={data,locale,t,period,maxDate,customRange};
  const content=useMemo(()=>({overview:<Overview {...shared} openSection={setSection}/>,journeys:<Journeys {...shared}/>,driving:<Driving {...shared}/>,charging:<Charging {...shared}/>,battery:<Battery {...shared}/>,activity:<Activity {...shared}/>,report:<Report data={data} locale={locale} t={t} minDate={minDate} maxDate={maxDate}/>,quality:<Quality data={data} locale={locale} t={t}/>,data:<DataSection data={data} locale={locale} t={t} busy={busy} onChoose={onChoose} onChooseHistory={onChooseHistory} onExport={onExport} onReset={onReset}/>})[section],[section,data,locale,t,period,minDate,maxDate,customRange,busy]);
  const filteredSections=["overview","journeys","driving","charging","battery","activity"];
  return <div className="dashboard-shell"><aside className="dashboard-sidebar"><div className="dashboard-brand"><span className="brand-mark"><img src={`${import.meta.env.BASE_URL}assets/xpeng-analytics-mark-minimal.png`} alt="" /></span><span><strong>XPENG</strong><small>Analytics</small></span></div><nav>{sections.map((item)=><button key={item} className={section===item?"is-active":""} onClick={()=>setSection(item)}><Icon name={item}/><span>{t(`nav_${item}`)}</span></button>)}</nav><div className="sidebar-bottom"><a className="sidebar-kofi" href="https://ko-fi.com/mpinto" target="_blank" rel="noreferrer">☕ {t("supportCta")}</a><div className="privacy-mini"><i/><span><strong>{t("localOnly")}</strong><small>{t("sessionOnly")}</small></span></div><small className="sidebar-version">XPENG Analytics · v{APP_VERSION}</small></div></aside><main className="dashboard-main"><header className="dashboard-topbar"><div><span className="dashboard-eyebrow">{t("dashboard")}</span><h1>{t(`section_${section}`)}</h1><p>{t(`section_${section}_help`)}</p></div><div className="topbar-actions"><button className="theme-toggle" type="button" onClick={onToggleTheme} aria-label={theme==="light"?t("darkTheme"):t("lightTheme")}><span/>{theme==="light"?t("dark"):t("light")}</button><label className="language-picker"><span>{t("language")}</span><select value={locale} onChange={(event)=>setLocale(event.target.value)}><option value="pt-PT">Português</option><option value="en">English</option></select></label></div></header><div className="mobile-nav">{sections.map((item)=><button key={item} className={section===item?"is-active":""} onClick={()=>setSection(item)} title={t(`nav_${item}`)}><Icon name={item}/></button>)}</div>{filteredSections.includes(section)?<PeriodBar period={period} setPeriod={setPeriod} customRange={customRange} setCustomRange={setCustomRange} minDate={minDate} maxDate={maxDate} t={t}/>:null}{busy?<div className="dashboard-progress"><div className="dashboard-progress-heading"><strong>{Math.round(progress.percent||0)}%</strong><span>{t(phaseKeys[progress.phase]||"loadingEngine")}{progress.detail?` · ${progress.detail}`:""}</span>{canCancel?<button className="cancel-processing" type="button" onClick={onCancel}>{t("cancelProcessing")}</button>:null}</div><div><i style={{width:`${Math.max(3,progress.percent||0)}%`}}/></div></div>:null}{error?<div className="dashboard-error">{t(`error_${error}`)}</div>:null}<div className="dashboard-content">{content}</div><footer className="site-footer dashboard-footer"><span>{t("unofficial")}</span><span>{t("ownerLabel")}: Miguel Pinto</span><span>v{APP_VERSION}</span><a href="https://logboox.app" target="_blank" rel="noreferrer">LogbooX</a><a href="https://github.com/josepinto1989/xpeng-analytics/issues" target="_blank" rel="noreferrer">{t("reportIssue")}</a><a href="https://ko-fi.com/mpinto" target="_blank" rel="noreferrer">Ko-fi</a></footer></main></div>;
}
